function cheapestTrip(maxTime: number, roads: number[][], fees: number[]): number {
  const n = fees.length;
  const dp: number[][] = Array.from({ length: maxTime + 1 }, () => new Array(n).fill(Infinity));
  dp[0][0] = fees[0];
  for (let t = 1; t <= maxTime; t++) {
    const row = dp[t];
    for (const [u, v, w] of roads) {
      if (w > t) continue;
      const prev = dp[t - w];
      if (prev[u] + fees[v] < row[v]) row[v] = prev[u] + fees[v];
      if (prev[v] + fees[u] < row[u]) row[u] = prev[v] + fees[u];
    }
  }
  let best = Infinity;
  for (let t = 0; t <= maxTime; t++) best = Math.min(best, dp[t][n - 1]);
  return best === Infinity ? -1 : best;
}

