class MinHeap {
  private a: number[][] = [];
  get size() { return this.a.length; }
  private less(i: number, j: number) {
    const x = this.a[i], y = this.a[j];
    return x[0] < y[0] || (x[0] === y[0] && x[1] < y[1]);
  }
  push(v: number[]) {
    const a = this.a; a.push(v);
    let i = a.length - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (!this.less(i, p)) break; [a[i], a[p]] = [a[p], a[i]]; i = p; }
  }
  pop(): number[] {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.less(l, m)) m = l;
        if (r < a.length && this.less(r, m)) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m], a[i]]; i = m;
      }
    }
    return top;
  }
}

function cheapestTrip(maxTime: number, roads: number[][], fees: number[]): number {
  const n = fees.length;
  const adj: number[][][] = Array.from({ length: n }, () => []);
  for (const [u, v, w] of roads) { adj[u].push([v, w]); adj[v].push([u, w]); }
  const fastest = new Array(n).fill(Infinity);
  const heap = new MinHeap();
  heap.push([fees[0], 0, 0]);
  while (heap.size) {
    const [fee, time, u] = heap.pop();
    if (u === n - 1) return fee;
    if (time >= fastest[u]) continue;
    fastest[u] = time;
    for (const [v, w] of adj[u]) {
      if (time + w <= maxTime && time + w < fastest[v]) heap.push([fee + fees[v], time + w, v]);
    }
  }
  return -1;
}

